  "I agree to the ": "Συμφωνώ με το εξής: ",
  "I am authorized to download and use this video.": "Έχω εξουσιοδότηση να κατεβάσω και να χρησιμοποιήσω αυτό το βίντεο.",
  "I hold documented consent or another verified legal basis.": "Έχω τεκμηριωμένη συγκατάθεση ή άλλη επαληθευμένη νομική βάση.",
  "I may download this reference and submit it to the AI analysis provider.": "Μπορώ να κατεβάσω αυτή την αναφορά και να την υποβάλω στον πάροχο ανάλυσης AI.",
  "I may use the prompt, brands, references, faces and voices in this generation.": "Μπορώ να χρησιμοποιήσω την εντολή, επωνυμίες, αναφορές, πρόσωπα και φωνές σε αυτή την παραγωγή.",
  "I may use this prompt, its brands, and its likenesses.": "Μπορώ να χρησιμοποιήσω αυτή την εντολή, τις επωνυμίες και τις απεικονίσεις προσώπων της.",
  "I may use this text and voice. If the voice identifies a real person, I have documented consent or another verified legal basis.": "Μπορώ να χρησιμοποιήσω αυτό το κείμενο και τη φωνή. Αν η φωνή ταυτοποιεί πραγματικό πρόσωπο, έχω τεκμηριωμένη συγκατάθεση ή άλλη επαληθευμένη νομική βάση.",
  "Idea — improvement request": "Ιδέα — αίτημα βελτίωσης",
  "Ideas": "Ιδέες",
  "Identity and contact details for the REELassati service provider.": "Στοιχεία ταυτότητας και επικοινωνίας του παρόχου REELassati.",
  "If a feature is not accessible, tell us the page, action, device, and assistive technology. We prioritise barriers affecting sign-in, purchase, creation, and account management: ": "Αν μια λειτουργία δεν είναι προσβάσιμη, πες μας σελίδα, ενέργεια, συσκευή και υποστηρικτική τεχνολογία. Δίνουμε προτεραιότητα σε εμπόδια σύνδεσης, αγοράς, δημιουργίας και διαχείρισης λογαριασμού: ",
  "If you buy as a consumer in the EEA or a country with equivalent rights, a statutory withdrawal period may apply, commonly 14 days for distance contracts. If you request immediate service, you may owe a proportionate amount for service already supplied. Loss of withdrawal rights for digital content occurs only when all legal requirements, including express consent and acknowledgement, are met. To exercise a right, send an unambiguous statement with your account email and purchase to ": "Αν αγοράζεις ως καταναλωτής στον ΕΟΧ ή σε χώρα με αντίστοιχα δικαιώματα, μπορεί να ισχύει νόμιμη περίοδος υπαναχώρησης, συνήθως 14 ημέρες για εξ αποστάσεως συμβάσεις. Αν ζητήσεις άμεση υπηρεσία, ίσως οφείλεις αναλογικό ποσό για όσα ήδη παρασχέθηκαν. Η απώλεια υπαναχώρησης για ψηφιακό περιεχόμενο επέρχεται μόνο όταν πληρούνται όλες οι νόμιμες προϋποθέσεις, συμπεριλαμβανομένης ρητής συγκατάθεσης και αναγνώρισης. Για άσκηση δικαιώματος στείλε σαφή δήλωση με e-mail λογαριασμού και αγορά στο ",
