  "Legal operator": "Νόμιμος διαχειριστής",
  "Legal remedies for a non-conforming digital service remain available. Failed generations automatically release reserved credits. For duplicate charges, missing access, undelivered credits, or persistent problems, contact support; we will verify payment and usage records and apply a refund, credit restoration, or another appropriate remedy.": "Τα νόμιμα μέσα αποκατάστασης για μη συμμορφούμενη ψηφιακή υπηρεσία παραμένουν διαθέσιμα. Οι αποτυχημένες παραγωγές αποδεσμεύουν αυτόματα δεσμευμένες μονάδες. Για διπλές χρεώσεις, έλλειψη πρόσβασης, μη παραδοθείσες μονάδες ή επίμονα προβλήματα, επικοινώνησε με υποστήριξη· θα ελέγξουμε πληρωμές και χρήση και θα εφαρμόσουμε επιστροφή, αποκατάσταση μονάδων ή άλλο κατάλληλο μέτρο.",
  "Legitimate interests: security, abuse prevention, reliability, legal claims, and strictly necessary operational measurement, balanced against user rights.": "Έννομα συμφέροντα: ασφάλεια, πρόληψη κατάχρησης, αξιοπιστία, νομικές αξιώσεις και απολύτως αναγκαία λειτουργική μέτρηση, σταθμισμένα με τα δικαιώματα χρηστών.",
