  "REELassati accessibility": "Προσβασιμότητα REELassati",
  "REELassati credits": "Μονάδες REELassati",
  "REELassati designs interfaces around WCAG 2.2 AA principles: semantic structure, accessible names, visible focus, contrast, keyboard navigation, reduced motion, and feedback that does not rely on colour alone. This is an operating target, not a claim of complete certified conformance.": "Το REELassati σχεδιάζει διεπαφές βάσει WCAG 2.2 AA: σημασιολογική δομή, προσβάσιμα ονόματα, ορατή εστίαση, αντίθεση, πλοήγηση πληκτρολογίου, μειωμένη κίνηση και ανατροφοδότηση που δεν βασίζεται μόνο στο χρώμα. Είναι λειτουργικός στόχος, όχι ισχυρισμός πλήρους πιστοποιημένης συμμόρφωσης.",
  "REELassati home": "Αρχική REELassati",
  "REELassati is intended for users aged 18 or older. Material changes to this notice will be communicated appropriately before they take effect.": "Το REELassati προορίζεται για χρήστες 18 ετών και άνω. Ουσιώδεις αλλαγές αυτής της ενημέρωσης θα γνωστοποιούνται κατάλληλα πριν ισχύσουν.",
  "REELassati provides tools to plan, create, edit, analyse, organise, and publish short-form content. You must be at least 18 and able to enter a contract. Anyone using the service for an organisation confirms authority to bind it.": "Το REELassati παρέχει εργαλεία σχεδιασμού, δημιουργίας, μοντάζ, ανάλυσης, οργάνωσης και δημοσίευσης σύντομου περιεχομένου. Πρέπει να είσαι τουλάχιστον 18 ετών και ικανός να συνάψεις σύμβαση. Η χρήση για οργανισμό επιβεβαιώνει εξουσία δέσμευσής του.",
  "REELassati updates this feed internally; no action or credits are required from you.": "Το REELassati ενημερώνει εσωτερικά αυτή τη ροή· δεν χρειάζεται ενέργεια ή μονάδες από εσένα.",
