  "Search transcript words, recorded scene observations, and clip names. Visual descriptions are searchable after source analysis exists. Search uses no AI credits. Meaning search compares English descriptions on your device against this existing text evidence.": "Αναζήτησε λέξεις απομαγνητοφώνησης, καταγεγραμμένες παρατηρήσεις σκηνών και ονόματα κλιπ. Οι οπτικές περιγραφές αναζητούνται αφού υπάρχει ανάλυση πηγής. Η αναζήτηση δεν χρησιμοποιεί μονάδες AI. Η σημασιολογική αναζήτηση συγκρίνει αγγλικές περιγραφές στη συσκευή σου με τα υπάρχοντα κειμενικά στοιχεία.",
