  "Select a stored audio asset or upload a new one. The app waits for the real transcription response before showing content.": "Επίλεξε αποθηκευμένο ηχητικό αρχείο ή μεταφόρτωσε νέο. Η εφαρμογή περιμένει πραγματική απάντηση απομαγνητοφώνησης πριν εμφανίσει περιεχόμενο.",
  "Select a video or image and move the playhead inside it to capture the current pose and grade.": "Επίλεξε βίντεο ή εικόνα και μετακίνησε την κεφαλή μέσα του για καταγραφή τρέχουσας στάσης και χρωματικής επεξεργασίας.",
