  "Select spoken words to remove their measured time from the footage, audio and other unlocked tracks, closing the gaps. No AI credits.": "Επίλεξε προφορικές λέξεις για αφαίρεση του μετρημένου χρόνου τους από υλικό, ήχο και άλλα ξεκλείδωτα κανάλια, κλείνοντας τα κενά. Χωρίς μονάδες AI.",
