  "Share a creator link and keep referrals attached. Rewards activate after paid-plan billing and signed purchase verification are connected.": "Μοιράσου σύνδεσμο δημιουργού και κράτησε τις συστάσεις συσχετισμένες. Οι ανταμοιβές ενεργοποιούνται αφού συνδεθούν χρέωση προγραμμάτων και υπογεγραμμένη επαλήθευση αγοράς.",
