  "Show recent files": "Εμφάνιση πρόσφατων αρχείων",
  "Sign-in sessions, security, abuse prevention, theme, language, selected workspace, interface state, and the privacy preference are needed to provide requested features. They may use cookies, localStorage, or sessionStorage and are not used for advertising.": "Συνεδρίες σύνδεσης, ασφάλεια, πρόληψη κατάχρησης, θέμα, γλώσσα, επιλεγμένος χώρος, κατάσταση διεπαφής και προτίμηση απορρήτου απαιτούνται για τις ζητούμενες λειτουργίες. Μπορεί να χρησιμοποιούν cookies, localStorage ή sessionStorage και δεν χρησιμοποιούνται για διαφήμιση.",
  "Sign-in, security, balance, preferences, and requested features.": "Σύνδεση, ασφάλεια, υπόλοιπο, προτιμήσεις και ζητούμενες λειτουργίες.",
