  "Static 1024 × 1024 image. Embedded PNG/JPEG textures and standard triangle meshes are supported. Export animated, skinned or compressed models as a static, uncompressed GLB first.": "Στατική εικόνα 1024 × 1024. Υποστηρίζονται ενσωματωμένες υφές PNG/JPEG και τυπικά τριγωνικά πλέγματα. Εξήγαγε πρώτα κινούμενα, σκελετικά ή συμπιεσμένα μοντέλα ως στατικό ασυμπίεστο GLB.",
