  "Still-image person segmentation; full-video matting and rotoscoping are not supported.": "Τμηματοποίηση προσώπου σε ακίνητη εικόνα· δεν υποστηρίζονται πλήρες ματάρισμα βίντεο και ροτοσκόπηση.",
  "Still-image relative depth; metric depth and tracked 3D reconstruction are not supported.": "Σχετικό βάθος ακίνητης εικόνας· δεν υποστηρίζονται μετρικό βάθος και παρακολουθούμενη ανακατασκευή 3D.",
