  "Submit report": "Υποβολή αναφοράς",
  "Subscriptions renew automatically for the displayed term until you disable renewal in the billing portal.": "Οι συνδρομές ανανεώνονται αυτόματα για τη δηλωμένη διάρκεια μέχρι να απενεργοποιήσεις την ανανέωση στην πύλη χρεώσεων.",
