  "Support messages, feedback, and account-related requests.": "Μηνύματα υποστήριξης, σχόλια και αιτήματα λογαριασμού.",
  "Support that acts": "Υποστήριξη που δρα",
  "Supporting text": "Συμπληρωματικό κείμενο",
