  "Uploading {{progress}}%": "Μεταφόρτωση {{progress}}%",
  "Upper captions that leave the lower frame clear.": "Επάνω υπότιτλοι που αφήνουν καθαρό το κάτω μέρος εικόνας.",
  "Urgent": "Επείγον",
  "Usage could not be loaded. Try Refresh.": "Η χρήση δεν φορτώθηκε. Δοκίμασε Ανανέωση.",
  "Use a PNG, JPEG or WebP image up to 20 MB.": "Χρησιμοποίησε εικόνα PNG, JPEG ή WebP έως 20 MB.",
  "Use a name and a valid range within the video, without overlapping another section.": "Χρησιμοποίησε όνομα και έγκυρο εύρος μέσα στο βίντεο χωρίς επικάλυψη άλλης ενότητας.",
  "Use a public link. Upload the file if the source requires sign-in.": "Χρησιμοποίησε δημόσιο σύνδεσμο. Μεταφόρτωσε το αρχείο αν η πηγή απαιτεί σύνδεση.",
  "Use a source-linked trend above or add your own observation.": "Χρησιμοποίησε παραπάνω τάση με πηγή ή πρόσθεσε δική σου παρατήρηση.",
  "Use a transparent PNG or WebP for a logo without a background.": "Χρησιμοποίησε διαφανές PNG ή WebP για λογότυπο χωρίς φόντο.",
  "Use as starting point": "Χρήση ως αφετηρία",
  "Use at least 8 characters. Your new password replaces the old one immediately.": "Χρησιμοποίησε τουλάχιστον 8 χαρακτήρες. Ο νέος κωδικός αντικαθιστά αμέσως τον παλιό.",
