  "Use wider spacing to stay within 48 cut points.": "Χρησιμοποίησε μεγαλύτερα διαστήματα για να μείνεις εντός 48 σημείων κοπής.",
  "User-selected content and instructions: prompts, scripts, files, media, projects, preferences, and outputs.": "Περιεχόμενο και οδηγίες που επιλέγει ο χρήστης: εντολές, σενάρια, αρχεία, μέσα, έργα, προτιμήσεις και αποτελέσματα.",
  "Uses existing media and measured speech. No AI credits. Apply creates one saved revision; Undo restores the previous edit.": "Χρησιμοποιεί υπάρχοντα μέσα και μετρημένη ομιλία. Χωρίς μονάδες AI. Η Εφαρμογή δημιουργεί μία αποθηκευμένη αναθεώρηση· η Αναίρεση επαναφέρει το προηγούμενο μοντάζ.",
  "Uses measured word timings from transcription. Imported subtitles or edited lines without word timings display the whole phrase.": "Χρησιμοποιεί μετρημένους χρόνους λέξεων απομαγνητοφώνησης. Εισαγόμενοι υπότιτλοι ή αλλαγμένες γραμμές χωρίς χρόνους λέξεων εμφανίζουν όλη τη φράση.",
  "Uses unused footage around the cut. Speech timing and total edit length stay fixed. Other overlapping video layers must be resolved first.": "Χρησιμοποιεί αχρησιμοποίητο υλικό γύρω από την κοπή. Χρονισμός ομιλίας και συνολικό μήκος μένουν σταθερά. Άλλα επικαλυπτόμενα οπτικά επίπεδα πρέπει να επιλυθούν πρώτα.",
  "Verified output": "Επαληθευμένο αποτέλεσμα",
  "Verified weekly picks are not available yet. Keep creating from your own idea while the next automatic check runs.": "Δεν υπάρχουν ακόμη επαληθευμένες εβδομαδιαίες επιλογές. Συνέχισε από δική σου ιδέα όσο εκτελείται ο επόμενος αυτόματος έλεγχος.",
  "Video analysis and custom trend research": "Ανάλυση βίντεο και προσαρμοσμένη έρευνα τάσεων",
