  "Voice rates: multilingual voices / existing language-specific voices. Voice is charged for the actual text length, rounded up to whole credits (minimum 1). Transcription is charged per started minute.": "Χρεώσεις φωνής: πολύγλωσσες / υπάρχουσες γλωσσικά εξειδικευμένες φωνές. Η φωνή χρεώνεται βάσει πραγματικού μήκους κειμένου, με στρογγυλοποίηση προς τα πάνω σε ακέραιες μονάδες (ελάχιστο 1). Η απομαγνητοφώνηση ανά ξεκινημένο λεπτό.",
