  "Waveform unavailable": "Κυματομορφή μη διαθέσιμη",
  "We may change or suspend features for security, law, maintenance, or provider changes. We do not promise marketing results, virality, or uninterrupted availability. Nothing excludes liability that law does not allow us to exclude or mandatory consumer remedies. Otherwise, total liability relating to the service is limited to the amount paid in the 12 months before the event.": "Μπορεί να αλλάξουμε ή να αναστείλουμε λειτουργίες για ασφάλεια, νόμο, συντήρηση ή αλλαγές παρόχων. Δεν υποσχόμαστε αποτελέσματα μάρκετινγκ, viral επιτυχία ή αδιάλειπτη διαθεσιμότητα. Τίποτα δεν αποκλείει ευθύνη που ο νόμος δεν επιτρέπει να αποκλειστεί ή υποχρεωτικά μέσα αποκατάστασης καταναλωτή. Διαφορετικά, η συνολική ευθύνη για την υπηρεσία περιορίζεται στο ποσό που πληρώθηκε τους 12 μήνες πριν το συμβάν.",
  "We may suspend an account for violations, security risk, non-payment, or legal duties, using proportionate measures. Italian law applies without depriving consumers of mandatory protections in their country of residence or mandatory courts. For support or complaints: ": "Μπορεί να αναστείλουμε λογαριασμό για παραβάσεις, κίνδυνο ασφάλειας, μη πληρωμή ή νομικές υποχρεώσεις, με αναλογικά μέτρα. Ισχύει το ιταλικό δίκαιο χωρίς στέρηση υποχρεωτικής προστασίας στη χώρα κατοικίας καταναλωτή ή υποχρεωτικής δικαιοδοσίας. Για υποστήριξη ή παράπονα: ",
  "We sent a secure confirmation link to": "Στείλαμε ασφαλή σύνδεσμο επιβεβαίωσης στο",
  "Weekly Coach": "Εβδομαδιαίος καθοδηγητής",
