  "Weekly picks use reachable direct TikTok and Reels source pages. Public dates and performance appear only when indexed evidence exposes them; unavailable values are never invented.": "Οι εβδομαδιαίες επιλογές χρησιμοποιούν προσβάσιμες άμεσες πηγές TikTok και Reels. Δημόσιες ημερομηνίες και απόδοση εμφανίζονται μόνο όταν υπάρχουν σε ευρετηριασμένα στοιχεία· μη διαθέσιμες τιμές δεν επινοούνται ποτέ.",
