  "What would you like to make?": "Τι θα ήθελες να δημιουργήσεις;",
  "Where applicable, you may request access, correction, deletion, restriction, portability, or objection; withdraw consent without affecting prior processing; and complain to the Italian Data Protection Authority or another competent authority. Account settings include data export and a deletion-request path.": "Όπου ισχύει, μπορείς να ζητήσεις πρόσβαση, διόρθωση, διαγραφή, περιορισμό, φορητότητα ή εναντίωση· να ανακαλέσεις συγκατάθεση χωρίς επίδραση στην προηγούμενη επεξεργασία· και να προσφύγεις στην ιταλική αρχή προστασίας δεδομένων ή άλλη αρμόδια αρχή. Οι ρυθμίσεις λογαριασμού περιλαμβάνουν εξαγωγή δεδομένων και διαδρομή αιτήματος διαγραφής.",
