  "Word cuts need measured word timings attached to audible video or audio. Captions without them remain editable in the caption controls.": "Οι κοπές λέξεων χρειάζονται μετρημένους χρόνους λέξεων σε ακουστό βίντεο ή ήχο. Οι υπότιτλοι χωρίς αυτούς παραμένουν επεξεργάσιμοι από τα χειριστήρια υποτίτλων.",
  "Word fade": "Σβήσιμο λέξης",
