  "You can always email": "Μπορείς πάντα να στείλεις e-mail στο",
  "You can disable renewal at any time in the billing portal. Access continues until the end of the paid period, subject to mandatory remedies or lawful suspension. Cancellation does not automatically refund the current term.": "Μπορείς να απενεργοποιήσεις ανανέωση οποτεδήποτε στην πύλη χρεώσεων. Η πρόσβαση συνεχίζεται μέχρι το τέλος πληρωμένης περιόδου, με επιφύλαξη υποχρεωτικών μέτρων αποκατάστασης ή νόμιμης αναστολής. Η ακύρωση δεν επιστρέφει αυτόματα το τρέχον ποσό.",
  "You choose whether to include additional suggestions.": "Επιλέγεις αν θα συμπεριλάβεις πρόσθετες προτάσεις.",
  "You keep ownership of content you upload. You grant REELassati and necessary providers a limited licence to host, process, transform, and transmit that content solely to provide requested features. You are responsible for required rights, licences, consents, and permissions, including for a real person’s image or voice.": "Διατηρείς την κυριότητα του περιεχομένου που μεταφορτώνεις. Παραχωρείς στο REELassati και απαραίτητους παρόχους περιορισμένη άδεια φιλοξενίας, επεξεργασίας, μετασχηματισμού και μεταφοράς αποκλειστικά για τις ζητούμενες λειτουργίες. Ευθύνεσαι για απαραίτητα δικαιώματα, άδειες, συγκαταθέσεις και εξουσιοδοτήσεις, μαζί με εικόνα ή φωνή πραγματικού προσώπου.",
  "Your account and data": "Ο λογαριασμός και τα δεδομένα σου",
