  "Content that violates law, intellectual-property, privacy, publicity, platform, or contractual rights.": "Περιεχόμενο που παραβιάζει νόμο, πνευματική ιδιοκτησία, απόρρητο, προσωπικότητα, κανόνες πλατφόρμας ή συμβατικά δικαιώματα.",
  "Controlled studio": "Ελεγχόμενο στούντιο",
