  "Creates a named image from a directed prompt and stores the marked output in the private media library.": "Δημιουργεί ονομασμένη εικόνα από κατευθυνόμενη εντολή και αποθηκεύει το σημασμένο αποτέλεσμα στην ιδιωτική βιβλιοθήκη μέσων.",
  "Creates scripts and proposed edit operations through a managed production route.": "Δημιουργεί σενάρια και προτεινόμενες ενέργειες μοντάζ μέσω διαχειριζόμενης διαδικασίας παραγωγής.",
