  "Employment, worker management, education admissions, credit, insurance, housing, medical, legal, policing, migration, or similar decisions about people.": "Αποφάσεις για απασχόληση, διαχείριση εργαζομένων, εισαγωγή στην εκπαίδευση, πιστώσεις, ασφάλιση, στέγαση, ιατρικά, νομικά, αστυνόμευση, μετανάστευση ή παρόμοια θέματα ανθρώπων.",
  "Evidence-based inspection": "Εξέταση βάσει στοιχείων",
  "Eye-level medium close-up, clean voice, gentle background falloff": "Μεσαίο κοντινό στο ύψος ματιών, καθαρή φωνή, απαλό θόλωμα φόντου",
  "Faded color, chroma noise, autofocus hunting, candid motion": "Ξεθωριασμένο χρώμα, χρωματικός θόρυβος, αναζήτηση αυτόματης εστίασης, αυθόρμητη κίνηση",
