  "Forward motion with a readable environment and real cadence": "Κίνηση εμπρός με ευανάγνωστο περιβάλλον και πραγματικό ρυθμό",
  "Generate a clean visual bed; render exact type in Studio": "Παραγωγή καθαρού οπτικού υποβάθρου· ακριβή γράμματα στο Στούντιο",
  "Generated supporting footage or narration when you hold the necessary rights.": "Παραγόμενο συμπληρωματικό υλικό ή αφήγηση όταν έχεις τα αναγκαία δικαιώματα.",
  "Generates a new clip or continues a previous one from a directed prompt and optional reference frames.": "Παράγει νέο κλιπ ή συνεχίζει προηγούμενο από κατευθυνόμενη εντολή και προαιρετικά καρέ αναφοράς.",
  "Handheld phone camera, window light, authentic room tone": "Κάμερα κινητού στο χέρι, φως παραθύρου, αυθεντικός ήχος δωματίου",
  "Help me with publishing": "Βοήθησέ με με τη δημοσίευση",
  "Hi — I’m REELassati Support. Tell me what you’re trying to do and what happened. I’ll troubleshoot it step by step, or prepare a complete support ticket when human help is the better route.": "Γεια — είμαι η Υποστήριξη REELassati. Πες μου τι προσπαθείς να κάνεις και τι συνέβη. Θα βοηθήσω βήμα-βήμα ή θα ετοιμάσω πλήρες αίτημα όταν ταιριάζει καλύτερα ανθρώπινη βοήθεια.",
  "High-contrast plate, graphic-safe space, rhythmic visual movement": "Φόντο υψηλής αντίθεσης, χώρος για γραφικά, ρυθμική οπτική κίνηση",
  "Hook and proof": "Ελκυστική εισαγωγή και τεκμηρίωση",
  "Human control": "Ανθρώπινος έλεγχος",
  "Human review": "Έλεγχος από άνθρωπο",
  "Human-approved publishing and scheduling for connected accounts.": "Δημοσίευση και προγραμματισμός με ανθρώπινη έγκριση για συνδεδεμένους λογαριασμούς.",
  "I can't access my account": "Δεν έχω πρόσβαση στον λογαριασμό μου",
  "I need to open a support ticket": "Χρειάζεται να ανοίξω αίτημα υποστήριξης",
  "If content appears to misuse your likeness, voice, work, or personal information, contact the human support channel with the relevant page, asset, or publication reference.": "Αν περιεχόμενο φαίνεται να καταχράται εικόνα, φωνή, έργο ή προσωπικά στοιχεία σου, επικοινώνησε με ανθρώπινη υποστήριξη με τη σχετική σελίδα, αρχείο ή αναφορά δημοσίευσης.",
  "Image generation": "Παραγωγή εικόνας",
  "Image, video, audio, JSON, or text · up to 64 MB · not retained": "Εικόνα, βίντεο, ήχος, JSON ή κείμενο · έως 64 MB · δεν διατηρείται",
  "Informational": "Ενημερωτικό",
  "Inspect available provenance": "Εξέταση διαθέσιμης προέλευσης",
  "Inspect pasted text or a media file for a REELassati provenance record and supported machine-readable signals. Inspection input is not retained. A missing signal means “not verified,” not “human-made.”": "Εξέτασε επικολλημένο κείμενο ή αρχείο μέσων για εγγραφή προέλευσης REELassati και υποστηριζόμενα μηχανικά αναγνώσιμα σήματα. Η είσοδος εξέτασης δεν διατηρείται. Η έλλειψη σήματος σημαίνει «μη επαληθευμένο», όχι «ανθρώπινο».",
  "Inspect provenance": "Εξέταση προέλευσης",
  "Inspecting evidence": "Εξέταση στοιχείων",
  "Inspection result": "Αποτέλεσμα εξέτασης",
  "Intended purpose": "Προβλεπόμενος σκοπός",
  "Intentional blocking, motivated light, and restrained movement": "Σκόπιμη τοποθέτηση ηθοποιών, δικαιολογημένο φως και συγκρατημένη κίνηση",
  "Landscape video": "Οριζόντιο βίντεο",
  "Macro material detail and a clear product action": "Μακρολεπτομέρεια υλικού και σαφής δράση προϊόντος",
  "Managed processing": "Διαχειριζόμενη επεξεργασία",
  "Manipulation, exploitation of vulnerability, unlawful surveillance, or collection of faces from the internet or CCTV to build recognition datasets.": "Χειραγώγηση, εκμετάλλευση ευαλωτότητας, παράνομη επιτήρηση ή συλλογή προσώπων από διαδίκτυο και κάμερες για σύνολα δεδομένων αναγνώρισης.",
  "Marking": "Σήμανση",
  "Match method": "Μέθοδος αντιστοίχισης",
  "Media transcription": "Απομαγνητοφώνηση μέσων",
  "Meeting": "Συνάντηση",
  "Missing": "Λείπει",
  "Motion-graphic plate": "Φόντο κινούμενων γραφικών",
  "Motivated camera move, atmospheric depth, filmic contrast": "Δικαιολογημένη κίνηση κάμερας, ατμοσφαιρικό βάθος, κινηματογραφική αντίθεση",
  "Music & sound effects": "Μουσική και ηχητικά εφέ",
  "Natural phone footage with believable framing imperfections": "Φυσικό υλικό κινητού με πειστικές ατέλειες καδραρίσματος",
  "Night color contrast": "Νυχτερινή χρωματική αντίθεση",
  "No result yet": "Δεν υπάρχει ακόμη αποτέλεσμα",
  "No verified match": "Χωρίς επαληθευμένη αντιστοίχιση",
  "Non-consensual impersonation, voice or likeness cloning, intimate synthetic content, harassment, fraud, or deceptive identity claims.": "Πλαστοπροσωπία χωρίς συγκατάθεση, κλωνοποίηση φωνής ή εικόνας, συνθετικό περιεχόμενο προσωπικού ή σεξουαλικού χαρακτήρα, παρενόχληση, απάτη ή παραπλανητικοί ισχυρισμοί ταυτότητας.",
  "Not found": "Δεν βρέθηκε",
  "Not reported": "Δεν αναφέρθηκε",
  "Not required": "Δεν απαιτείται",
  "Not supported": "Δεν υποστηρίζεται",
  "Nothing is sent for AI processing or publishing until you trigger generation, analysis, transcription, speech, or publishing.": "Τίποτα δεν στέλνεται για επεξεργασία AI ή δημοσίευση μέχρι να ξεκινήσεις παραγωγή, ανάλυση, απομαγνητοφώνηση, ομιλία ή δημοσίευση.",
