  "Clip start": "Αρχή κλιπ",
  "Comments": "Σχόλια",
  "Compare plans and review the final terms in checkout.": "Σύγκρινε προγράμματα και έλεγξε τους τελικούς όρους στο ταμείο.",
  "Compare posts and publication history, then choose one improvement for the next piece. Use Goals or Weekly Review to keep that action visible.": "Σύγκρινε αναρτήσεις και ιστορικό δημοσίευσης, μετά επίλεξε μία βελτίωση για το επόμενο περιεχόμενο. Χρησιμοποίησε Στόχους ή Εβδομαδιαία ανασκόπηση για να τη διατηρήσεις ορατή.",
  "Compare the displayed credits, connected-account limits, and billing period. Choose the option you need, then review the final checkout amount and terms.": "Σύγκρινε μονάδες, όρια συνδεδεμένων λογαριασμών και περίοδο χρέωσης. Επίλεξε αυτό που χρειάζεσαι και έλεγξε τελικό ποσό και όρους στο ταμείο.",
  "Complete any verification shown after signup. If you already have an account, use Sign in to keep your existing work together.": "Ολοκλήρωσε τυχόν επαλήθευση μετά την εγγραφή. Αν έχεις ήδη λογαριασμό, χρησιμοποίησε Σύνδεση για να μείνει μαζί η υπάρχουσα εργασία.",
  "Complete the password reset opened from your email link.": "Ολοκλήρωσε την επαναφορά κωδικού που άνοιξες από το e-mail.",
