  "Describe the composition": "Περιγραφή σύνθεσης",
  "Describe the idea, audience, and outcome. Concrete experiences give the interview more useful material than broad claims.": "Περίγραψε ιδέα, κοινό και αποτέλεσμα. Οι συγκεκριμένες εμπειρίες δίνουν πιο χρήσιμο υλικό συνέντευξης από γενικούς ισχυρισμούς.",
