  "Fill in positioning, audience, and voice using concrete examples. Add the colors, visual references, and editing preferences that should stay consistent.": "Συμπλήρωσε τοποθέτηση, κοινό και φωνή με συγκεκριμένα παραδείγματα. Πρόσθεσε χρώματα, οπτικές αναφορές και προτιμήσεις μοντάζ που πρέπει να μείνουν συνεπείς.",
