  "Follow the next step": "Ακολούθησε το επόμενο βήμα",
  "Follow the source links": "Ακολούθησε τους συνδέσμους πηγών",
  "For a suggestion, describe the task you are trying to finish and how the change would help. Review the form before sending.": "Για πρόταση, περίγραψε την εργασία που προσπαθείς να τελειώσεις και πώς θα βοηθούσε η αλλαγή. Έλεγξε τη φόρμα πριν στείλεις.",
  "From": "Από",
  "Gain for {{name}}": "Ενίσχυση για {{name}}",
  "Generate a directed shot with a clear subject, action, and camera plan.": "Παρήγαγε σκηνοθετημένη λήψη με σαφές θέμα, δράση και πλάνο κάμερας.",
  "Generated video preview: {{name}}": "Προεπισκόπηση παραγόμενου βίντεο: {{name}}",
  "Generating": "Παραγωγή",
  "Get focused help": "Λήψη στοχευμένης βοήθειας",
  "Get help with a specific task or send an issue for human review.": "Ζήτησε βοήθεια για συγκεκριμένη εργασία ή στείλε ζήτημα για ανθρώπινο έλεγχο.",
  "Give files descriptive names and use the available folders and favorites. Keep source footage distinct from final exports.": "Δώσε περιγραφικά ονόματα αρχείων και χρησιμοποίησε φακέλους και αγαπημένα. Κράτησε το πηγαίο υλικό χωριστά από τελικές εξαγωγές.",
  "Give the draft substance": "Δώσε ουσία στο προσχέδιο",
  "Go to Dashboard after sign-in to create and edit real projects.": "Μετά τη σύνδεση πήγαινε στον Πίνακα ελέγχου για δημιουργία και μοντάζ πραγματικών έργων.",
  "Go to Publisher to select destinations for a post. Disconnect an account only when you no longer want the studio to use that connection.": "Πήγαινε στο Εργαλείο δημοσίευσης για επιλογή προορισμών ανάρτησης. Αποσύνδεσε λογαριασμό μόνο όταν δεν θέλεις πια να χρησιμοποιείται η σύνδεσή του.",
  "Go to audio gain key {{number}}": "Μετάβαση σε σημείο ενίσχυσης ήχου {{number}}",
  "Go to {{evidence}} match in {{name}} at {{time}}": "Μετάβαση στην αντιστοίχιση {{evidence}} στο {{name}} στις {{time}}",
  "Graphics": "Γραφικά",
  "Guide: {{title}}": "Οδηγός: {{title}}",
  "Guide: {{title}} (?)": "Οδηγός: {{title}} (?)",
  "Highlight": "Επισήμανση",
  "Hold until next keyframe": "Διατήρηση έως το επόμενο καρέ-κλειδί",
  "Hold, then jump": "Κράτημα και μετά άλμα",
  "Horizontal %": "Οριζόντια %",
  "Horizontal position": "Οριζόντια θέση",
  "If a ticket is prepared, review its subject, description, and contact details before sending it. A prepared ticket is sent only after you submit it.": "Αν ετοιμαστεί αίτημα, έλεγξε θέμα, περιγραφή και στοιχεία επικοινωνίας πριν το στείλεις. Το έτοιμο αίτημα στέλνεται μόνο όταν το υποβάλεις.",
  "If the page reports a failure, return to Sign in and try the same account method again. Include the error when contacting support.": "Αν η σελίδα αναφέρει αποτυχία, επέστρεψε στη Σύνδεση και δοκίμασε ξανά τον ίδιο τρόπο λογαριασμού. Πρόσθεσε το σφάλμα στην επικοινωνία με υποστήριξη.",
  "If you received a code, enter it in the claim section and read the confirmation or eligibility message.": "Αν έλαβες κωδικό, βάλε τον στην ενότητα διεκδίκησης και διάβασε επιβεβαίωση ή μήνυμα επιλεξιμότητας.",
  "If you used a social sign-in provider, use that provider’s access flow. Contact support if the account remains inaccessible.": "Αν χρησιμοποίησες κοινωνικό πάροχο σύνδεσης, ακολούθησε τη διαδικασία πρόσβασής του. Επικοινώνησε με υποστήριξη αν ο λογαριασμός παραμένει απρόσιτος.",
  "Impressions": "Εμφανίσεις",
  "In Studio profile, review your details and timezone. Save changes before leaving the section.": "Στο προφίλ Στούντιο έλεγξε στοιχεία και ζώνη ώρας. Αποθήκευσε αλλαγές πριν φύγεις από την ενότητα.",
  "In speech synthesis, filter voices and languages, read their tags, and play a sample. Generate from the final text after reviewing the credit cost, then use the audio file in your edit.": "Στη σύνθεση ομιλίας, φίλτραρε φωνές και γλώσσες, διάβασε χαρακτηριστικά και άκουσε δείγμα. Παρήγαγε από τελικό κείμενο αφού ελέγξεις κόστος μονάδων και χρησιμοποίησε τον ήχο στο μοντάζ.",
  "Include the project or file name and any error message. Keep passwords and API keys out of the report.": "Πρόσθεσε όνομα έργου ή αρχείου και τυχόν σφάλμα. Μη βάζεις κωδικούς ή κλειδιά API στην αναφορά.",
  "Include your specific example, evidence, and intended takeaway. Describe the tone you want and any facts or promises the script must avoid.": "Πρόσθεσε συγκεκριμένο παράδειγμα, στοιχεία και επιθυμητό συμπέρασμα. Περίγραψε τόνο και όσα γεγονότα ή υποσχέσεις πρέπει να αποφεύγει το σενάριο.",
  "Inspect and save": "Εξέταση και αποθήκευση",
  "Inspect the preset": "Εξέταση προρύθμισης",
  "Inspect the source": "Εξέταση πηγής",
