  "Join REELassati with my creator link. I earn {{credits}} credits ({{value}} of product value) after you buy a paid plan.": "Μπες στο REELassati με τον σύνδεσμο δημιουργού μου. Κερδίζω {{credits}} μονάδες ({{value}} αξία προϊόντος) αφού αγοράσεις πρόγραμμα επί πληρωμή.",
  "Keep brand and appearance separate": "Διαχώρισε επωνυμία και εμφάνιση",
