  "Move between months or return to today. Select a day to see its items; filters separate your events from publications.": "Άλλαξε μήνες ή επέστρεψε στο σήμερα. Επίλεξε ημέρα για τα στοιχεία της· τα φίλτρα χωρίζουν τα συμβάντα από δημοσιεύσεις.",
