  "Working": "Σε εξέλιξη",
  "Write from a brief for a defined idea, or choose Interview me to develop it through questions. Set the audience, goal, and intended length.": "Γράψε από οδηγίες για συγκεκριμένη ιδέα ή επίλεξε Κάνε μου συνέντευξη για ανάπτυξη μέσω ερωτήσεων. Όρισε κοινό, στόχο και επιθυμητή διάρκεια.",
  "Yesterday": "Χθες",
