  "Your media on the left, preview in the center, Reel on the right, and the timeline below.": "Τα μέσα αριστερά, η προεπισκόπηση στο κέντρο, το Reel δεξιά και η χρονογραμμή κάτω.",
  "Your studio": "Το στούντιό σου",
  "Your studio’s Plan & credits page holds balance, usage, top-ups, and the available subscription-management controls.": "Η σελίδα Πρόγραμμα και μονάδες του στούντιο περιέχει υπόλοιπο, χρήση, πρόσθετες αγορές και διαθέσιμα χειριστήρια διαχείρισης συνδρομής.",
